<?php /** 赛事业务视图；负责人：王乐之（2411302）；AI辅助开发。 */ use yii\helpers\Html;$this->title=$team->name;?><h1><?= Html::encode($team->name) ?></h1><p>FIFA 代码：<?= Html::encode($team->fifa_code) ?></p><?php if(!Yii::$app->user->isGuest):?><?= Html::beginForm(['favorite/toggle','type'=>'team','id'=>$team->id],'post') ?><button>收藏 / 取消收藏球队</button><?= Html::endForm() ?><?php endif ?><h2>参赛球员</h2><div class="grid"><?php foreach($team->players as $p):?><div class="card"><?= Html::a(Html::encode($p->name),['player/view','id'=>$p->id]) ?> · <?= Html::encode($p->position) ?></div><?php endforeach ?></div><h2>比赛记录</h2><table><?php foreach($matches as $m):?><tr><td><?= Html::encode($m->kicks_off_at) ?></td><td><?= Html::a(Html::encode($m->homeTeam->name.' vs '.$m->awayTeam->name),['match/view','id'=>$m->id]) ?></td><td><?= (int)$m->normal_home+(int)$m->extra_home ?>:<?= (int)$m->normal_away+(int)$m->extra_away ?></td></tr><?php endforeach ?></table>